# Ajuste de hiperparámetros para el mejor modelo
if best_model_name == 'Random Forest':
    param_grid = {
        'n_estimators': [100, 200, 300],
        'max_depth': [5, 10, 15],
        'min_samples_split': [2, 5, 10]
    }
    best_model = RandomForestRegressor(random_state=42)
elif best_model_name == 'Gradient Boosting':
    param_grid = {
        'n_estimators': [100, 200, 300],
        'max_depth': [3, 5, 7],
        'learning_rate': [0.01, 0.1, 0.2]
    }
    best_model = GradientBoostingRegressor(random_state=42)
elif best_model_name == 'Support Vector Machine':
    param_grid = {
        'C': [0.1, 1, 10],
        'epsilon': [0.01, 0.1, 1]
    }
    best_model = SVR()
elif best_model_name == 'K-Nearest Neighbors':
    param_grid = {
        'n_neighbors': [3, 5, 7],
        'weights': ['uniform', 'distance']
    }
    best_model = KNeighborsRegressor()
else:
    best_model = LinearRegression()
    param_grid = {}
    # Si el modelo tiene hiperparámetros, realizar GridSearchCV
if param_grid:
    grid_search = GridSearchCV(estimator=best_model, param_grid=param_grid, cv=5, n_jobs=-1, scoring='neg_mean_squared_error')
    grid_search.fit(X, y)
    best_model = grid_search.best_estimator_
    print(f"Mejores hiperparámetros encontrados para {best_model_name}: {grid_search.best_params_}")

